package main

import (
	"fmt"
	"log"
	"os"
	"time"

	"github.com/linn221/learning-concurrency/oct27/findDuplicateFiles/lib"
)

// run => go run . ../../dumps
// taking 18 seconds on my machine with the folder generated by writeDuplicateFiles
func main() {
	if len(os.Args) < 2 {
		log.Fatal("program use: ./program dir")
	}

	start := time.Now()
	results := lib.SearchDir(os.Args[1])
	t := time.Since(start).Round(time.Millisecond) //not counting the printing time
	for hash, fileList := range results {
		if len(fileList) > 1 {
			fmt.Printf("%s\n", hash)
			for _, path := range fileList {
				fmt.Printf("\t%s\n", path)
			}
			fmt.Println()
		}
	}
	fmt.Println(t)
}
